public ZnMatrix(ZnMatrix m) {
    this(m.getRowCount(), m.getColumnCount(), m.getModulus());
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            coefficients[r][c] = m.coefficients[r][c];
        }
    }
}

