public static void Print(String name, float[][] m) {
    int righe = m.length;
    int colonne = m[0].length;
    System.out.println(name + ":");
    System.out.println("------------");
    for (int yr = 0; yr  righe; yr++) {
        for (int yc = 0; yc  colonne; yc++) {
            System.out.print(m[yr][yc] + " , ");
        }
        System.out.println();
    }
    System.out.println("------------");
}

