    int lines = M.length;
    int columns = M[0].length;
    float[][] MInv = new float[lines][columns];
    for (int i = 0; i  lines; i++) {
        for (int j = 0; j  columns; j++) {
            MInv[i][j] = M[i][columns - j - 1];
        }
    }
    return MInv;
}

