public static double[][] random(int m, int n, double min, double max) {
    double[][] array = new double[m][n];
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            array[i][j] = min + Random.raw() * (max - min);
        }
    }
    return array;
