protected double[][] addComponents(Matrix a) {
    int n = this.rows();
    int m = this.columns();
    double[][] newComponents = new double[n][m];
    for (int i = 0; i  n; i++) {
        for (int j = 0; j  n; j++) newComponents[i][j] = components[i][j] + a.components[i][j];
    }
    return newComponents;
}

