protected double[][] productComponents(double a) {
    int n = this.rows();
    int m = this.columns();
    double[][] newComponents = new double[n][m];
    for (int i = 0; i  n; i++) {
        for (int j = 0; j  m; j++) newComponents[i][j] = a * components[i][j];
