    double[][] data = this.Data;
    double[][] newData = new double[m][n];
    for (int ni = 0; ni  n; ni++) {
        for (int mi = 0; mi  m; mi++) {
            newData[mi][ni] = data[mi][ni] * scalar;
        }
    }
    return new MathRealMatrix(newData);
}

