    this.n = n;
    A = new double[m][n];
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            A[i][j] = s;
        }
    }
}

public PNMatrix plus(PNMatrix B) {
    checkMatrixDimensions(B);
    PNMatrix X = new PNMatrix(m, n);
    int[][] C = X.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            C[i][j] = A[i][j] + B.A[i][j];
        }
    }
    return X;
}

public Matrix copy() {
    Matrix X = new Matrix(m, n);
    double[][] C = X.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            C[i][j] = A[i][j];
        }
    }
    return X;
}

