public float[][] createNullMatrix(int r, int c) {
    float[][] mat = new float[r][c];
    for (int i = 0; i  r; i++) {
        for (int j = 0; j  c; j++) {
            mat[i][j] = 0.0f;
        }
    }
    return mat;
}

