public ZnMatrix(ZMatrix m, int modulus) {
    this(m.getRowCount(), m.getColumnCount(), modulus);
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            coefficients[r][c] = NumberTheory.mod(m.get(r, c), modulus);
        }
    }
}

