public static double[][] multiply(double arg1, double arg2[][], double result[][]) {
    int rows = arg2.length;
    int cols = arg2[0].length;
    for (int i = 0; i  rows; i++) {
        for (int j = 0; j  cols; j++) {
            result[i][j] = arg1 * arg2[i][j];
        }
    }
    return result;
}

