public static double[][] sum(double[][] A, double[][] B) {
    if (logger.isDebugEnabled()) {
        debug("Matrix A:", A);
        debug("Matrix B:", B);
    }
    int _dimension = A.length;
    double[][] C = new double[_dimension][_dimension];
    for (int i = 0; i  _dimension; i++) {
        for (int k = 0; k  _dimension; k++) {
            C[i][k] = B[i][k] + A[i][k];
        }
    }
