public static double[][] mult(double[][] m1, double a) {
    int m = m1.length;
    int n = m1[0].length;
    double[][] ret = new double[n][n];
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            ret[i][j] = m1[i][j] * a;
        }
    }
    return ret;
}

