        throw new IllegalArgumentException("Length of 3rd and 4th arguments must = second argument");
    }
    double[][] array = new double[m][n];
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            array[i][j] = begin[j] + i * pitch[j];
        }
    }
    return array;
}

