    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            coefficients[r][c] = new Complex(m.get(r, c));
        }
    }
}

public PNMatrix minusEquals(PNMatrix B) {
    checkMatrixDimensions(B);
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            A[i][j] = A[i][j] - B.A[i][j];
        }
    }
    return this;
}

