private static Complex[][] makeArray(int rows, int columns) {
    Complex[][] res = new Complex[rows][columns];
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            res[r][c] = Complex.getZero();
        }
    }
    return res;
}

