protected double[][] getAdjunta(double[][] matriz) {
    int size = matriz.length;
    double[][] nova = new double[size][size];
    for (int i = 0; i  size; i++) {
        for (int j = 0; j  size; j++) {
            nova[i][j] = getCofator(matriz, i, j);
        }
    }
    return getTransposta(nova);
}

public static PNMatrix identity(int m, int n) {
    PNMatrix A = new PNMatrix(m, n);
    int[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = (i == j ? 1 : 0);
        }
    }
    return A;
}

public static double[][] doubleClone(float[][] matrix) {
    int nr = matrix.length;
    int nc = matrix[0].length;
    double[][] cmatrix = new double[nr][nc];
    for (int r = 0; r  nr; r++) {
        for (int c = 0; c  nc; c++) {
            cmatrix[r][c] = matrix[r][c];
        }
    }
    return cmatrix;
}

