public Matrix(int rows, int columns, double... _elements) {
    elements = new double[rows][columns];
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            elements[r][c] = _elements[r * columns + c];
        }
    }
}

