public static CMatrix identity(int m, int n) {
    CMatrix A = new CMatrix(m, n);
    Complex[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = (i == j ? Complex.ONE : Complex.ZERO);
        }
    }
    return A;
}

