public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
    rows = in.readInt();
    columns = in.readInt();
    in.readByte();
    self = new double[rows][columns];
    for (int i = 0; i  rows; i++) {
        for (int j = 0; j  columns; j++) {
            self[i][j] = in.readDouble();
            in.readByte();
        }
    }
}

