public static double[][] add(double[][] m1, double[][] m2) {
    int m = m1.length;
    int n = m1[0].length;
    assert (m == m2.length);
    assert (n == m2[0].length);
    double[][] ret = new double[m][n];
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            ret[i][j] = m1[i][j] + m2[i][j];
        }
    }
    return ret;
}

