    double[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = Math.random();
        }
    }
    return A;
}

public ZMatrix(ZnMatrix m) {
    this(m.getRowCount(), m.getColumnCount());
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            coefficients[r][c] = m.get(r, c);
        }
    }
}

public static Matrix identity(int m, int n) {
    Matrix A = new Matrix(m, n);
    double[][] X = A.getArray();
    for (int i = 0; i  m; i++) {
        for (int j = 0; j  n; j++) {
            X[i][j] = (i == j ? 1.0 : 0.0);
        }
    }
    return A;
}

