        }
    }
}

public static LImage[][] reversalXandY(final LImage[][] array) {
    int col = array[0].length;
    int row = array.length;
    LImage[][] result = new LImage[col][row];
    for (int y = 0; y  col; y++) {
        for (int x = 0; x  row; x++) {
            result[x][y] = array[y][x];
        }
    }
    return result;
}

public ZMatrix(ZnMatrix m) {
    this(m.getRowCount(), m.getColumnCount());
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            coefficients[r][c] = m.get(r, c);
        }
    }
}

public static int[][] reversalXandY(final int[][] array) {
    int col = array[0].length;
    int row = array.length;
    int[][] result = new int[col][row];
    for (int y = 0; y  col; y++) {
        for (int x = 0; x  row; x++) {
            result[x][y] = array[y][x];
        }
    }
    return result;
}

