private static Rational[][] makeArray(int rows, int columns) {
    Rational[][] res = new Rational[rows][columns];
    for (int r = 0; r  rows; r++) {
        for (int c = 0; c  columns; c++) {
            res[r][c] = Rational.getZero();
        }
    }
    return res;
}

