private Object[][] transform(Object[][] src) {
    int col = src.length;
    int row = src[0].length;
    Object[][] dest = new Object[row][col];
    for (int i = 0; i  col; i++) {
        for (int j = 0; j  row; j++) {
            dest[j][i] = src[i][j];
        }
    }
    return dest;
}

